"""MEASURED read graph of the from-scratch command (generation 22, V22-D8).

verify_all.py carries a hand-written READS table and refuses to start when a reader is ordered
before its producer. A hand-written table can itself be wrong (generation-22 drafting listed
phase4.py as reading the trace vector when it actually reads runs/*.store.json, which were then
produced LATER in the command). This stage measures the graph instead: for every stage module and
every local module it imports, each artifact path literal under runs/ vectors/ envelopes/ query/
traces/ notes/ is classified as a write (the literal reaches EV.write / json.dump / open(..., 'w'))
or a read, and each read is joined to the stage(s) whose modules write it. It fails when a stage
reads an artifact whose FIRST producer is ordered at or after it, and when the measured graph is
not covered by verify_all.READS.
"""
import ast
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.dirname(HERE)
LIT = re.compile(r"""['"]/?((?:runs|vectors|envelopes|query|traces|notes)/[\w.%*{}-]+\.json)['"]""")


def stages():
    src = open(os.path.join(HERE, 'verify_all.py'), encoding='utf-8').read()
    tree = ast.parse(src)
    out, reads = [], {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and node.targets[0].id == 'STAGES':
            for elt in node.value.elts:
                out.append(ast.literal_eval(elt.elts[1])[0])
        if isinstance(node, ast.Assign) and node.targets[0].id == 'READS':
            reads = ast.literal_eval(node.value)
    return out, reads


def local_imports(mod, seen):
    if mod in seen or not os.path.exists(os.path.join(HERE, mod)):
        return seen
    seen.add(mod)
    tree = ast.parse(open(os.path.join(HERE, mod), encoding='utf-8').read())
    for n in ast.walk(tree):
        names = []
        if isinstance(n, ast.Import):
            names = [a.name for a in n.names]
        elif isinstance(n, ast.ImportFrom) and n.module:
            names = [n.module]
        for nm in names:
            local_imports(nm.split('.')[0] + '.py', seen)
    return seen


def pattern(lit):
    return re.compile('^' + re.sub(r'%[sd]|\\\*|\\\{[^}]*\\\}', r'[^/]+', re.escape(lit)) + '$')


def classify(mod):
    reads, writes = set(), set()
    for line in open(os.path.join(HERE, mod), encoding='utf-8'):
        s = line.strip()
        if s.startswith('#'):
            continue
        for m in LIT.finditer(line):
            lit = m.group(1)
            if re.search(r"EV\.write\(|write_json\(|dump\(|,\s*['\"]w['\"]\)|\.save\(|export\(", line):
                writes.add(lit)
            else:
                reads.add(lit)
    return reads, writes


def main():
    order, declared = stages()
    first = {}
    for i, m in enumerate(order):
        first.setdefault(m, i)
    per_stage = {}
    for m in first:
        rs, ws = set(), set()
        for dep in sorted(local_imports(m, set())):
            r, w = classify(dep)
            if dep == m:
                rs |= r
            ws |= w
        per_stage[m] = (rs - ws, ws)
    edges, violations, unmatched, undeclared = [], [], [], []
    for reader, (rs, _ws) in per_stage.items():
        for lit in sorted(rs):
            pat = pattern(lit)
            producers = sorted({p for p, (_r, ws) in per_stage.items() if p != reader
                                and any(pat.match(w) or pattern(w).match(lit) for w in ws)},
                               key=lambda p: first[p])
            if not producers:
                unmatched.append({'reader': reader, 'artifact': lit})
                continue
            p = producers[0]
            edges.append({'reader': reader, 'artifact': lit, 'firstProducer': p,
                          'readerStage': first[reader], 'producerStage': first[p]})
            if first[p] >= first[reader]:
                violations.append(edges[-1])
            if p not in declared.get(reader, []):
                undeclared.append({'reader': reader, 'producer': p, 'artifact': lit})
    doc = {'standing': __doc__, 'edges': edges, 'violations': violations,
           'readsWithNoProducerStage': unmatched,
           'readsNotDeclaredInVerifyAllREADS': undeclared,
           'result': 'PASS' if not violations and not undeclared else 'REFUSE'}
    os.makedirs(OUT + '/notes', exist_ok=True)
    with open(OUT + '/notes/v22-read-graph.json', 'w') as fh:
        json.dump(doc, fh, indent=1)
    print('read graph: %d edges, %d order violations, %d undeclared, %d with no producer stage'
          % (len(edges), len(violations), len(undeclared), len(unmatched)))
    for v in violations:
        print('  ORDER', v)
    for u in undeclared[:40]:
        print('  UNDECLARED', u)
    sys.exit(0 if doc['result'] == 'PASS' else 1)


if __name__ == '__main__':
    main()

